CREATE TABLE IF NOT EXISTS supplier_commitment_events (
 id INTEGER PRIMARY KEY,
 commitment_id TEXT NOT NULL CHECK(length(commitment_id) BETWEEN 3 AND 96),
 event_type TEXT NOT NULL CHECK(event_type IN ('approved','paused','ended','superseded','occurrence_matched')),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),
 payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),
 previous_payload_hash TEXT,
 idempotency_key TEXT,
 actor TEXT NOT NULL,
 principal TEXT NOT NULL,
 created_at TEXT NOT NULL,
 UNIQUE(commitment_id,event_type,payload_hash),
 UNIQUE(idempotency_key)
);
CREATE VIEW IF NOT EXISTS current_supplier_commitments AS
 SELECT e.* FROM supplier_commitment_events e
 WHERE e.event_type='approved' AND NOT EXISTS (SELECT 1 FROM supplier_commitment_events x WHERE x.commitment_id=e.commitment_id AND x.event_type IN ('paused','ended','superseded') AND x.id>e.id);
CREATE INDEX IF NOT EXISTS supplier_commitment_events_commitment ON supplier_commitment_events(commitment_id,id);
CREATE TRIGGER IF NOT EXISTS supplier_commitment_events_no_update BEFORE UPDATE ON supplier_commitment_events BEGIN SELECT RAISE(ABORT, 'supplier commitment events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS supplier_commitment_events_no_delete BEFORE DELETE ON supplier_commitment_events BEGIN SELECT RAISE(ABORT, 'supplier commitment events are append-only'); END;
